import assert from 'node:assert/strict';
import test from 'node:test';
import { AccessService } from '../lib/handlers/shared/providers';
import {
  createLockerClient,
  MockLockerClient,
  MqttLockerClient,
  setLockerClientOverride,
} from '../lib/handlers/shared/providers/lockers';
import { parseIotScanEvent, handler as verifyEntryHandler } from '../lib/handlers/verify-entry';

test('Locker Client Suite - 1. MockLockerClient builds correct payload and topic', async () => {
  const mockClient = new MockLockerClient();
  const lockerId = 'locker-101';

  const payload = await mockClient.openLocker(lockerId);

  assert.deepStrictEqual(payload, {
    id: 1,
    method: 'Switch.Set',
    params: {
      id: 0,
      on: true,
      toggle_after: 5,
    },
  });

  assert.strictEqual(mockClient.sentCommands.length, 1);
  assert.strictEqual(mockClient.sentCommands[0].lockerId, lockerId);
  assert.strictEqual(mockClient.sentCommands[0].topic, 'gym/lockers/locker-101/command');
  assert.deepStrictEqual(mockClient.sentCommands[0].payload, payload);
});

test('Locker Client Suite - 2. MockLockerClient allows custom params', async () => {
  const mockClient = new MockLockerClient();
  const lockerId = 'locker-202';

  const payload = await mockClient.openLocker(lockerId, { id: 2, toggle_after: 10 });

  assert.deepStrictEqual(payload, {
    id: 1,
    method: 'Switch.Set',
    params: {
      id: 2,
      on: true,
      toggle_after: 10,
    },
  });
});

test('Locker Client Suite - 3. createLockerClient factory handles type selection', () => {
  const mockClient = createLockerClient('mock');
  assert.ok(mockClient instanceof MockLockerClient);

  const mqttClient = createLockerClient('mqtt', 'test-endpoint.iot.eu-central-1.amazonaws.com');
  assert.ok(mqttClient instanceof MqttLockerClient);
});

test('Locker Client Suite - 4. parseIotScanEvent ignores an untrusted lockerId when provided', () => {
  const scanEvent = {
    event_id: 'evt-123',
    client_id: 'scanner-01',
    lockerId: 'locker-777',
    timestamp: 1785672769,
    payload: {
      raw_data: 'mock:user_abc',
      encoding: 'utf-8',
    },
  };

  const parsed = parseIotScanEvent(scanEvent);
  assert.strictEqual(parsed.valid, true);
  if (parsed.valid) {
    assert.strictEqual(parsed.scannerId, 'scanner-01');
    assert.equal('lockerId' in parsed, false);
  }
});

test('Locker Client Suite - 5. verifyEntryHandler sends feedback to scanner and opens locker via LockerClient', async () => {
  process.env.MAIN_TABLE_NAME = 'TestMainTable';
  process.env.ENTRY_LOGS_TABLE_NAME = 'TestEntryLogsTable';

  const originalCommitAccess = AccessService.prototype.commitAccess;
  AccessService.prototype.commitAccess = async (_scannerId: string, _credential: any) => {
    return { success: true, entryId: 'test-entry-123', lockerId: 'assigned-locker-02' };
  };

  try {
    const mockLockerClient = new MockLockerClient();
    setLockerClientOverride(mockLockerClient);

    const scanEvent = {
      event_id: 'evt-456',
      client_id: 'scanner-02',
      lockerId: 'untrusted-locker-id',
      timestamp: Math.floor(Date.now() / 1000),
      payload: {
        raw_data: 'mock:user_xyz',
        encoding: 'utf-8',
      },
    };

    const result: any = await verifyEntryHandler(scanEvent);

    assert.strictEqual(result.result, 'success');
    assert.strictEqual(result.action, 'open_gate');
    assert.strictEqual(result.lockerId, 'assigned-locker-02');
    assert.deepStrictEqual(result.lockerPayload, {
      id: 1,
      method: 'Switch.Set',
      params: {
        id: 0,
        on: true,
        toggle_after: 5,
      },
    });

    assert.strictEqual(mockLockerClient.sentCommands.length, 1);
    assert.strictEqual(mockLockerClient.sentCommands[0].topic, 'gym/lockers/assigned-locker-02/command');
  } finally {
    setLockerClientOverride(undefined);
    AccessService.prototype.commitAccess = originalCommitAccess;
  }
});

export * from './types';
export * from './access-service';
export * from './qr';
export * from './payment';
export * from './identity';
export * from './reader';

export interface IdentityProvider {
  ensureUser(userPoolId: string, email: string): Promise<string>;
}

export interface LockProvider {
  sendUnlockCommand(params: { ip: string; port?: number; path?: string; durationSeconds: number }): Promise<void>;
}

export interface PaymentProvider {
  createCheckoutSession(params: {
    priceId?: string;
    successUrl: string;
    cancelUrl: string;
    customerEmail?: string;
    metadata?: Record<string, string>;
    enableTax?: boolean;
  }): Promise<{ url: string }>;

  createPortalSession(params: { customerId: string; returnUrl: string }): Promise<{ url: string }>;

  listInvoices(params: { customerId: string }): Promise<
    Array<{
      id: string;
      number: string | null;
      pdfUrl: string | null;
      total: number;
      tax: number;
      currency: string;
      status: string | null;
      createdAt: string;
    }>
  >;

  constructWebhookEvent(payload: string | Buffer, signature: string): Promise<any>;
}

export type ProviderId = 'tilde-v1-3-0' | 'basic-subscription' | 'mock' | 'unsupported';

export interface IotPayload {
  raw_data: string;
  encoding: string;
}

export interface IotScanEvent {
  event_id: string;
  client_id: string;
  timestamp: number;
  payload: IotPayload;
}

export interface RawDataClassification {
  status: 'recognized' | 'unrecognized';
  providerId?: ProviderId;
  rawData: string;
  reason?: string;
}

export interface VerifiedCredential {
  subjectId: string;
  providerId: ProviderId;
  metadata?: Record<string, unknown>;
}

export interface VerificationResult {
  success: boolean;
  credential?: VerifiedCredential;
  reason?: string;
}

export interface CommitResult {
  success: boolean;
  entryId?: string;
  lockerId?: string;
  reason?: string;
}

export interface ParsedTildeV130Data {
  version: string;
  serialNumber: string;
  headerCode: string;
  keyValues: Record<string, string>;
  segments: string[];
  signature?: string;
}

export interface MqttFeedbackPayload {
  result: 'success' | 'denied';
  reason?: string;
  feedback?: string;
  entryId?: string;
  action?: 'open_gate' | 'none';
  timestamp: string;
}

export interface IProvider {
  readonly id: ProviderId;
  canHandle(rawData: string): boolean;
  verify(rawData: string, context?: Record<string, unknown>): Promise<VerificationResult>;
}

export interface IProviderClassifier {
  classify(rawData: string): Promise<RawDataClassification>;
  registerProvider(provider: IProvider): void;
}

export interface IMqttFeedbackPublisher {
  sendFeedback(scannerId: string, feedback: MqttFeedbackPayload): Promise<void>;
  sendDenial(scannerId: string, reason?: string): Promise<MqttFeedbackPayload>;
  sendGateUnlockSignal(scannerId: string, entryId: string): Promise<MqttFeedbackPayload>;
}

import { AccessRepository } from '../repositories';
import { BasicSubscriptionProvider, DefaultProviderClassifier, MockProvider, TildeV130Provider } from './qr';
import { CommitResult, VerificationResult, VerifiedCredential } from './types';

export class AccessService {
  private classifier: DefaultProviderClassifier;

  constructor(
    private readonly repository: AccessRepository,
    private readonly now: () => Date = () => new Date()
  ) {
    this.classifier = new DefaultProviderClassifier([
      new TildeV130Provider(),
      new BasicSubscriptionProvider(
        async () => {
          const keys = await this.repository.getQrSigningKeys();
          if (!keys.currentKey) {
            throw new Error('HMAC_CURRENT_KEY is not configured');
          }
          return { currentKey: keys.currentKey, previousKey: keys.previousKey };
        },
        (userId) => this.repository.getUserSubscription(userId)
      ),
      new MockProvider(),
    ]);
  }

  async verifyRawData(rawData: string): Promise<VerificationResult> {
    const classification = await this.classifier.classify(rawData);

    if (classification.status !== 'recognized' || !classification.providerId) {
      return { success: false, reason: classification.reason || 'unrecognized_format' };
    }

    const provider = this.classifier.getProvider(classification.providerId);
    if (!provider) {
      return { success: false, reason: 'provider_not_found' };
    }

    return provider.verify(rawData);
  }

  async commitAccess(scannerId: string, credential: VerifiedCredential): Promise<CommitResult> {
    const scanner = await this.repository.findActiveScanner(scannerId);
    if (!scanner) {
      return { success: false, reason: 'unknown_or_inactive_scanner' };
    }
    if (!scanner.assigned_locker_id?.trim()) {
      return { success: false, reason: 'scanner_unassigned_locker' };
    }
    // Enforce scanner's allowed_qr_providers whitelist
    if (!scanner.allowed_qr_providers.includes(credential.providerId as any)) {
      return { success: false, reason: 'unavailable' };
    }

    const commitTime = this.now();
    const result = await this.repository.commitAccess({
      scanner,
      credential,
      scannerId,
      committedAt: commitTime.toISOString(),
      committedAtEpochSeconds: Math.floor(commitTime.getTime() / 1000),
    });
    if (result.outcome === 'committed' && result.entryId) {
      return { success: true, entryId: result.entryId, lockerId: scanner.assigned_locker_id };
    }
    if (result.outcome === 'anti_passback_cooldown') {
      return { success: false, reason: 'anti_passback_cooldown' };
    }
    return { success: false, reason: 'transaction_failed' };
  }
}

export * from './classifier/provider-classifier';
export * from './custom-tilde-provider';
export * from './basic-subscription-provider';
export * from './mock-provider';

import { IProvider, IProviderClassifier, RawDataClassification } from '../../types';

export class DefaultProviderClassifier implements IProviderClassifier {
  private readonly providers: Map<string, IProvider> = new Map();

  constructor(providers?: IProvider[]) {
    if (providers) {
      for (const p of providers) {
        this.registerProvider(p);
      }
    }
  }

  registerProvider(provider: IProvider): void {
    this.providers.set(provider.id, provider);
  }

  getProvider(id: string): IProvider | undefined {
    return this.providers.get(id);
  }

  async classify(rawData: string): Promise<RawDataClassification> {
    if (typeof rawData !== 'string' || !rawData.trim()) {
      return {
        status: 'unrecognized',
        rawData: rawData || '',
        reason: 'raw_data_empty',
      };
    }

    for (const provider of this.providers.values()) {
      if (provider.canHandle(rawData)) {
        return {
          status: 'recognized',
          providerId: provider.id,
          rawData,
        };
      }
    }

    return {
      status: 'unrecognized',
      rawData,
      reason: 'no_matching_provider',
    };
  }
}

import { IProvider, ParsedTildeV130Data, ProviderId, VerificationResult } from '../types';

export class TildeV130Provider implements IProvider {
  readonly id: ProviderId = 'tilde-v1-3-0';

  canHandle(rawData: string): boolean {
    return typeof rawData === 'string' && (rawData.startsWith('1.3.0~') || rawData.startsWith('1.'));
  }

  parseTildeData(rawData: string): ParsedTildeV130Data {
    const parts = rawData.split('~');
    const version = parts[0] || '1.3.0';
    const serialNumber = parts[1] || '';
    const headerCode = parts[2] || '';
    const kvString = parts[3] || '';

    const keyValues: Record<string, string> = {};
    if (kvString) {
      for (const pair of kvString.split('|')) {
        if (!pair) continue;
        const [k, v] = pair.split('=');
        if (k && v !== undefined) keyValues[k] = v;
      }
    }

    const segments = parts.length > 5 ? parts.slice(4, parts.length - 1) : [];
    const signature = parts.length > 4 ? parts[parts.length - 1] : undefined;

    return {
      version,
      serialNumber,
      headerCode,
      keyValues,
      segments,
      signature,
    };
  }

  async verify(rawData: string, context?: Record<string, unknown>): Promise<VerificationResult> {
    if (!this.canHandle(rawData)) {
      return { success: false, reason: 'unrecognized_format' };
    }

    try {
      const parsed = this.parseTildeData(rawData);
      const subjectId = parsed.keyValues['4'] || parsed.serialNumber;

      if (!subjectId) {
        return { success: false, reason: 'missing_subject_id' };
      }

      // Check expiration date if key '6' (YYYYMMDD) is present
      const validUntilStr = parsed.keyValues['6'];
      if (validUntilStr && validUntilStr.length === 8) {
        const year = parseInt(validUntilStr.substring(0, 4), 10);
        const month = parseInt(validUntilStr.substring(4, 6), 10) - 1;
        const day = parseInt(validUntilStr.substring(6, 8), 10);
        const validUntil = new Date(Date.UTC(year, month, day, 23, 59, 59));

        const now = context?.now instanceof Date ? (context.now as Date) : new Date();
        if (now > validUntil) {
          return { success: false, reason: 'credential_expired' };
        }
      }

      return {
        success: true,
        credential: {
          subjectId,
          providerId: this.id,
          metadata: {
            version: parsed.version,
            serialNumber: parsed.serialNumber,
            keyValues: parsed.keyValues,
            segments: parsed.segments,
            signature: parsed.signature,
          },
        },
      };
    } catch (err) {
      return {
        success: false,
        reason: 'malformed_tilde_data',
      };
    }
  }
}

import { signQrPayload } from '../../crypto';
import { IProvider, ProviderId, VerificationResult } from '../types';

interface BasicQrPayload {
  user_id: string;
  timestamp: number;
  hmac: string;
}

export type KeyFetcher = () => Promise<{ currentKey: string; previousKey?: string }>;
export type SubscriptionFetcher = (
  userId: string
) => Promise<{ status: string; grace_period_end?: string } | undefined>;

const missingKeyFetcher: KeyFetcher = async () => {
  throw new Error('QR signing-key fetcher is required');
};

const missingSubscriptionFetcher: SubscriptionFetcher = async () => {
  throw new Error('Subscription fetcher is required');
};

export class BasicSubscriptionProvider implements IProvider {
  readonly id: ProviderId = 'basic-subscription';

  constructor(
    private readonly keyFetcher: KeyFetcher = missingKeyFetcher,
    private readonly subscriptionFetcher: SubscriptionFetcher = missingSubscriptionFetcher
  ) {}

  private async getKeys(): Promise<{ currentKey: string; previousKey?: string }> {
    return this.keyFetcher();
  }

  private async getSubscription(userId: string) {
    return this.subscriptionFetcher(userId);
  }

  canHandle(rawData: string): boolean {
    if (typeof rawData !== 'string' || !rawData.trim().startsWith('{')) return false;
    try {
      const parsed = JSON.parse(rawData);
      return typeof parsed === 'object' && parsed !== null && ('user_id' in parsed || 'hmac' in parsed);
    } catch {
      return false;
    }
  }

  async verify(rawData: string, context?: Record<string, unknown>): Promise<VerificationResult> {
    if (!this.canHandle(rawData)) {
      return { success: false, reason: 'unrecognized_format' };
    }

    try {
      const payload = JSON.parse(rawData) as Partial<BasicQrPayload>;

      if (
        typeof payload.user_id !== 'string' ||
        typeof payload.timestamp !== 'number' ||
        typeof payload.hmac !== 'string'
      ) {
        return { success: false, reason: 'invalid_payload_structure' };
      }

      const now =
        typeof context?.nowSeconds === 'number' ? (context.nowSeconds as number) : Math.floor(Date.now() / 1000);
      if (Math.abs(now - payload.timestamp) > 60) {
        return { success: false, reason: 'qr_expired' };
      }

      const { currentKey, previousKey } = await this.getKeys();

      const currentHmac = signQrPayload(payload.user_id, payload.timestamp, currentKey);
      const previousHmac = previousKey ? signQrPayload(payload.user_id, payload.timestamp, previousKey) : undefined;

      if (payload.hmac !== currentHmac && payload.hmac !== previousHmac) {
        return { success: false, reason: 'invalid_hmac' };
      }

      const subscription = await this.getSubscription(payload.user_id);
      const subscriptionActive =
        subscription?.status === 'ACTIVE' ||
        (subscription?.status === 'PAST_DUE' &&
          subscription.grace_period_end &&
          new Date(subscription.grace_period_end).getTime() / 1000 > now);

      if (!subscriptionActive) {
        return { success: false, reason: 'subscription_inactive' };
      }

      return {
        success: true,
        credential: {
          subjectId: payload.user_id,
          providerId: this.id,
          metadata: { timestamp: payload.timestamp },
        },
      };
    } catch (err) {
      return { success: false, reason: 'malformed_json_payload' };
    }
  }
}

import { createHash, createHmac } from 'crypto';

/** Hash API key using SHA-256 */
export function hashApiKey(apiKey: string): string {
  return createHash('sha256').update(apiKey).digest('hex');
}

/** Compute HMAC signature for QR code payload verification */
export function signQrPayload(userId: string, timestamp: number, secretKey: string): string {
  return createHmac('sha256', secretKey).update(`${userId}:${timestamp}`).digest('hex');
}

import { IProvider, ProviderId, VerificationResult } from '../types';

export class MockProvider implements IProvider {
  readonly id: ProviderId = 'mock';

  canHandle(rawData: string): boolean {
    return typeof rawData === 'string' && rawData.startsWith('mock:');
  }

  async verify(rawData: string, _context?: Record<string, unknown>): Promise<VerificationResult> {
    if (!this.canHandle(rawData)) {
      return { success: false, reason: 'unrecognized_format' };
    }

    const subjectId = rawData.slice('mock:'.length).trim();
    if (!subjectId) {
      return { success: false, reason: 'missing_mock_subject_id' };
    }

    return {
      success: true,
      credential: {
        subjectId,
        providerId: this.id,
      },
    };
  }
}

import { PaymentProvider } from '../types';
import { StripePaymentProvider } from './stripe-payment-provider';
import { MockPaymentProvider } from './mock-payment-provider';

export { StripePaymentProvider } from './stripe-payment-provider';
export { MockPaymentProvider } from './mock-payment-provider';
export { getStripeClient, getWebhookSecret } from './stripe-client-manager';

const paymentProviders: Record<string, new () => PaymentProvider> = {
  stripe: StripePaymentProvider,
  mock: MockPaymentProvider,
};

export function createPaymentProvider(type: string): PaymentProvider {
  const ProviderClass = paymentProviders[type];
  if (!ProviderClass) {
    throw new Error(`Unsupported payment provider type: '${type}'`);
  }
  return new ProviderClass();
}

import Stripe from 'stripe';
import { PaymentProvider } from '../types';
import { getStripeClient, getWebhookSecret } from './stripe-client-manager';

export class StripePaymentProvider implements PaymentProvider {
  async createCheckoutSession(params: {
    priceId?: string;
    successUrl: string;
    cancelUrl: string;
    customerEmail?: string;
    metadata?: Record<string, string>;
    enableTax?: boolean;
  }): Promise<{ url: string }> {
    const stripe = await getStripeClient();

    // Generate random 8-character suffix for integration_identifier tracking
    const randomSuffix = Math.random().toString(36).substring(2, 10);

    const isExplicitStripePrice =
      params.priceId && params.priceId.startsWith('price_') && params.priceId !== 'price_monthly';

    const sessionParams: Stripe.Checkout.SessionCreateParams = {
      mode: 'subscription',
      success_url: params.successUrl,
      cancel_url: params.cancelUrl,
      line_items: isExplicitStripePrice
        ? [{ price: params.priceId, quantity: 1 }]
        : [
            {
              price_data: {
                currency: 'usd',
                product_data: {
                  name: 'CrossBox Gym Monthly All-Access Membership',
                  description: 'Unlimited access to all CrossBox Gym locations, turnstile keycard, and mobile app.',
                },
                recurring: { interval: 'month' },
                unit_amount: 4900,
                tax_behavior: 'exclusive',
              },
              quantity: 1,
            },
          ],
      customer_email: params.customerEmail,
      metadata: {
        integration_check: `checkout_${randomSuffix}`,
        ...(params.metadata || {}),
      },
      automatic_tax: { enabled: true },
      tax_id_collection: { enabled: true },
    };

    try {
      const session = await stripe.checkout.sessions.create(sessionParams);
      return { url: session.url! };
    } catch (err: any) {
      if (err.message?.includes('No such price') || err.message?.includes('resource_missing')) {
        sessionParams.line_items = [
          {
            price_data: {
              currency: 'usd',
              product_data: {
                name: 'CrossBox Gym Monthly All-Access Membership',
                description: 'Unlimited access to all CrossBox Gym locations, turnstile keycard, and mobile app.',
              },
              recurring: { interval: 'month' },
              unit_amount: 4900,
              tax_behavior: 'exclusive',
            },
            quantity: 1,
          },
        ];
        const session = await stripe.checkout.sessions.create(sessionParams);
        return { url: session.url! };
      }
      if (
        err.message?.includes('tax') ||
        err.message?.includes('head office address') ||
        err.message?.includes('automatic_tax')
      ) {
        delete sessionParams.automatic_tax;
        const session = await stripe.checkout.sessions.create(sessionParams);
        return { url: session.url! };
      }
      throw err;
    }
  }

  async createPortalSession(params: { customerId: string; returnUrl: string }): Promise<{ url: string }> {
    const stripe = await getStripeClient();
    try {
      const session = await stripe.billingPortal.sessions.create({
        customer: params.customerId,
        return_url: params.returnUrl,
      });
      return { url: session.url };
    } catch (err: any) {
      if (
        err.message?.includes('No such customer') ||
        err.message?.includes('resource_missing') ||
        err.code === 'resource_missing'
      ) {
        return { url: `${params.returnUrl}?portal_mock=true` };
      }
      throw err;
    }
  }

  async listInvoices(params: { customerId: string }): Promise<
    Array<{
      id: string;
      number: string | null;
      pdfUrl: string | null;
      total: number;
      tax: number;
      currency: string;
      status: string | null;
      createdAt: string;
    }>
  > {
    const stripe = await getStripeClient();
    const invoices = await stripe.invoices.list({
      customer: params.customerId,
      limit: 24,
    });

    return invoices.data.map((inv) => ({
      id: inv.id,
      number: inv.number,
      pdfUrl: inv.invoice_pdf || null,
      total: inv.total,
      tax: (inv as any).tax || (inv as any).amount_tax || 0,
      currency: inv.currency,
      status: inv.status,
      createdAt: new Date(inv.created * 1000).toISOString(),
    }));
  }

  async constructWebhookEvent(payload: string, signature: string): Promise<any> {
    const stripe = await getStripeClient();
    const secret = await getWebhookSecret();
    return stripe.webhooks.constructEvent(payload, signature, secret);
  }
}

import { SSMClient, GetParameterCommand } from '@aws-sdk/client-ssm';
import Stripe from 'stripe';
import { getStripeSecretKeySsmPath, getStripeWebhookSecretSsmPath } from '../../config';

let stripeClient: Stripe | null = null;
let webhookSecret: string | null = null;
const ssm = new SSMClient({});

/**
 * Lazily initializes and caches a Stripe client instance.
 * Resolves the API key from environment variables first, then falls back to SSM Parameter Store.
 */
export async function getStripeClient(): Promise<Stripe> {
  if (stripeClient) return stripeClient;

  const directKey = process.env.STRIPE_TEST_SECRET_KEY || process.env.STRIPE_SECRET_KEY;
  if (directKey) {
    stripeClient = new Stripe(directKey, { apiVersion: '2026-06-24.dahlia' as any });
    return stripeClient;
  }

  try {
    const ssmPath = getStripeSecretKeySsmPath();
    const res = await ssm.send(new GetParameterCommand({ Name: ssmPath, WithDecryption: true }));
    const key = res.Parameter?.Value;
    if (key) {
      stripeClient = new Stripe(key, { apiVersion: '2026-06-24.dahlia' as any });
      return stripeClient;
    }
  } catch (e) {
    // SSM parameter does not exist in dev/test stack
  }

  throw new Error('Could not retrieve Stripe secret key');
}

/**
 * Lazily initializes and caches the Stripe webhook signing secret from SSM Parameter Store.
 */
export async function getWebhookSecret(): Promise<string> {
  if (webhookSecret) return webhookSecret;
  const ssmPath = getStripeWebhookSecretSsmPath();
  const res = await ssm.send(new GetParameterCommand({ Name: ssmPath, WithDecryption: true }));
  const secret = res.Parameter?.Value;
  if (!secret) throw new Error('Could not retrieve Stripe webhook secret');
  webhookSecret = secret;
  return webhookSecret;
}

export function getMainTableName(): string {
  const name = process.env.MAIN_TABLE_NAME;
  if (!name) throw new Error('MAIN_TABLE_NAME environment variable is required');
