export class MqttLockerClient implements ILockerClient {
  private iotDataClients = new Map<string, IoTDataPlaneClient>();
  private readonly configProvider: ILockerConfigProvider;

  constructor(endpointOrConfigProvider: string | ILockerConfigProvider) {
    if (typeof endpointOrConfigProvider === 'string') {
      const endpointStr = endpointOrConfigProvider;
      this.configProvider = {
        async getConfig() {
          return {
            endpoint: endpointStr,
            lockerThingName: 'crossbox-locker-relay-01',
          };
        },
      };
    } else {
      this.configProvider = endpointOrConfigProvider;
    }
  }

  async openLocker(lockerId?: string, options?: Partial<LockerCommandParams>): Promise<LockerCommandPayload> {
    const config = await this.configProvider.getConfig();
    const targetLockerId = lockerId && lockerId.trim() ? lockerId.trim() : config.lockerThingName;

    if (!targetLockerId) {
      throw new Error('lockerId or default lockerThingName is required to open locker');
    }

    let client = this.iotDataClients.get(config.endpoint);
    if (!client) {
      client = new IoTDataPlaneClient(config.endpoint ? { endpoint: `https://${config.endpoint}` } : {});
      this.iotDataClients.set(config.endpoint, client);
    }

    const payload: LockerCommandPayload = {
      id: 1,
      method: 'Switch.Set',
      params: {
        id: options?.id ?? 0,
        on: options?.on ?? true,
        toggle_after: options?.toggle_after ?? 5,
      },
    };

    const topic = `gym/lockers/${targetLockerId}/command`;

    try {
      await client.send(
        new PublishCommand({
          topic,
          qos: 1,
          payload: Buffer.from(JSON.stringify(payload)),
        })
      );
      console.log(`[MqttLockerClient] Published unlock command to ${topic}:`, payload);
    } catch (err) {
      console.warn(`[MqttLockerClient] Failed to send MQTT unlock command to locker ${targetLockerId}:`, err);
      throw err;
    }

    return payload;
  }
}

import { GetParametersCommand, SSMClient } from '@aws-sdk/client-ssm';

export interface LockerConfig {
  endpoint: string;
  lockerThingName: string;
}

export interface ILockerConfigProvider {
  getConfig(): Promise<LockerConfig>;
}

export interface SsmLockerConfigOptions {
  endpointParameterName: string;
  lockerThingNameParameterName: string;
  fallbackConfig: LockerConfig;
}

export class SsmLockerConfigProvider implements ILockerConfigProvider {
  private ssm?: SSMClient;
  private cachedConfig?: LockerConfig;

  constructor(private readonly options: SsmLockerConfigOptions) {}

  async getConfig(): Promise<LockerConfig> {
    if (this.cachedConfig) {
      return this.cachedConfig;
    }

    try {
      if (!this.ssm) {
        this.ssm = new SSMClient({});
      }

      const res = await this.ssm.send(
        new GetParametersCommand({
          Names: [this.options.endpointParameterName, this.options.lockerThingNameParameterName],
          WithDecryption: false,
        })
      );

      const map = new Map<string, string>();
      for (const p of res.Parameters || []) {
        if (p.Name && p.Value) {
          map.set(p.Name, p.Value);
        }
      }

      const endpoint = map.get(this.options.endpointParameterName) || this.options.fallbackConfig.endpoint;
      const lockerThingName =
        map.get(this.options.lockerThingNameParameterName) || this.options.fallbackConfig.lockerThingName;

      this.cachedConfig = { endpoint, lockerThingName };
      return this.cachedConfig;
    } catch (err) {
      console.warn('[SsmLockerConfigProvider] Failed to fetch SSM parameters, using configured fallback:', err);
      this.cachedConfig = this.options.fallbackConfig;
      return this.cachedConfig;
    }
  }
}

